"""The stack ops: transport bytecode, which co_code, .pyc files and dis hold.

One row per stack op and per pseudo-instruction of the compiler.  Their only
semantics are the translator's lowering rules (Python/regcfg.c); this table
holds what the opcode generators and the translator's tables read of them:
numbers (pinned below), cache units, deopt bases, flags, stack
effects and the translator's format row (`StackFormat`).  It is data.
"""

from dataclasses import dataclass


@dataclass(frozen=True)
class StackFormat:
    """The translator's row of a stack op (`_PyStackFormat`), then the columns
    that _PyIRFormat still has for it and that the word format drops."""
    flags: tuple[str, ...]          # _PyIR_<name>: WINDOW, JUMPS, FORWARD, ...
    effects: tuple[str, ...]        # _PyIR_<name>: PURE, RAISES, ...
    roles: tuple[str, str, str, str]  # _PyIR_ROLE_<name>, `IN0+k` for inputs
    imm: str                        # _PyIR_LOC_<name>
    ninputs: int
    dst: int | None                 # None: _PyIR_NO_DST
    borrow_mask: int
    operands: str                   # _PyIR_OPERANDS_<name>
    through: tuple[int, str]        # (k, form): _PyIR_EXT_<form>
    # Legacy columns of _PyIRFormat for a stack op, dropped with the word
    # format split (R/wf/design.md)
    output_kind: str                # _PyIR_OUTPUT_<name>
    observer: tuple[str, str]       # _PyIR_OBSERVER_<name>
    reads: tuple[int, str]
    writes: tuple[int, str]


@dataclass(frozen=True)
class StackOp:
    name: str
    opcode: int
    size: int                       # code units: the op and its cache entries
    family: str | None              # the base op that a specialised form deopts to
    flags: tuple[str, ...]          # HAS_<name>_FLAG: ARG, CONST, NAME, JUMP, FREE, LOCAL, EVAL_BREAK
    oparg: bool                     # takes an oparg (decides the format of a specialised op)
    popped: str                     # C expression of oparg
    pushed: str
    translator_only: bool = False   # a CFG number in the gap, in no co_code
    stack_only: bool = False        # a format for the CFG and no handler
    format: StackFormat | None = None


@dataclass(frozen=True)
class Pseudo:
    name: str
    opcode: int
    flags: tuple[str, ...]
    as_sequence: bool
    targets: tuple[str, ...]
    popped: str
    pushed: str


